// Reutiliza el ticket de acceso (dura 12 h): ARCA rechaza pedir uno nuevo si el anterior sigue vigente.
const item = $input.first();
let ta = null;
try {
  if (item.binary?.data) ta = JSON.parse((await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8'));
} catch (e) { ta = null; }
const vigente = !!(ta && ta.token && ta.sign && new Date(ta.expira).getTime() - Date.now() > 10 * 60 * 1000);
return [{ json: vigente ? { vigente, ok: true, token: ta.token, sign: ta.sign, expira: ta.expira } : { vigente: false } }];

// Arma el pedido de acceso (TRA), lo firma con el certificado del CeCIP (CMS SHA-256) y prepara el SOAP.
// Requiere en el servidor de n8n: NODE_FUNCTION_ALLOW_BUILTIN=crypto
const crypto = require('crypto');
// Firma CMS (PKCS#7 SignedData, SHA-256 + RSA) del TRA de ARCA usando solo el módulo crypto de Node.
// Se usa tal cual dentro del Code node de n8n (requiere NODE_FUNCTION_ALLOW_BUILTIN=crypto).
function firmarCms(traXml, certPem, keyPem, crypto) {
  const len = (n) => {
    if (n < 0x80) return Buffer.from([n]);
    const b = [];
    while (n > 0) { b.unshift(n & 0xff); n >>= 8; }
    return Buffer.from([0x80 | b.length, ...b]);
  };
  const tlv = (tag, ...partes) => { const c = Buffer.concat(partes); return Buffer.concat([Buffer.from([tag]), len(c.length), c]); };
  const seq = (...p) => tlv(0x30, ...p);
  const set = (...p) => tlv(0x31, ...p);
  const oid = (s) => {
    const n = s.split(".").map(Number);
    const out = [40 * n[0] + n[1]];
    for (const v of n.slice(2)) {
      const b = [v & 0x7f];
      let x = v >> 7;
      while (x > 0) { b.unshift((x & 0x7f) | 0x80); x >>= 7; }
      out.push(...b);
    }
    return tlv(0x06, Buffer.from(out));
  };
  const nulo = Buffer.from([0x05, 0x00]);
  const entero = (n) => tlv(0x02, Buffer.from([n]));
  const octetos = (b) => tlv(0x04, b);
  const ctx = (n, ...p) => tlv(0xa0 + n, ...p);

  // Lector DER mínimo: devuelve los elementos hijos de una estructura (con sus bytes crudos)
  const hijos = (buf) => {
    const out = [];
    let i = 0;
    while (i < buf.length) {
      const tag = buf[i];
      let l = buf[i + 1], h = 2;
      if (l & 0x80) { const nb = l & 0x7f; l = 0; for (let k = 0; k < nb; k++) l = (l << 8) | buf[i + 2 + k]; h = 2 + nb; }
      out.push({ tag, raw: buf.subarray(i, i + h + l), contenido: buf.subarray(i + h, i + h + l) });
      i += h + l;
    }
    return out;
  };

  const certDer = Buffer.from(certPem.replace(/-----[^-]+-----/g, "").replace(/\s+/g, ""), "base64");
  const tbs = hijos(hijos(certDer)[0].contenido)[0];
  const campos = hijos(tbs.contenido);
  const desde = campos[0].tag === 0xa0 ? 1 : 0; // el campo version es opcional
  const serial = campos[desde].raw;
  const emisor = campos[desde + 2].raw;

  const OID = {
    data: "1.2.840.113549.1.7.1", signedData: "1.2.840.113549.1.7.2", sha256: "2.16.840.1.101.3.4.2.1",
    rsa: "1.2.840.113549.1.1.1", contentType: "1.2.840.113549.1.9.3", messageDigest: "1.2.840.113549.1.9.4",
    signingTime: "1.2.840.113549.1.9.5",
  };
  const contenido = Buffer.from(traXml, "utf8");
  const digest = crypto.createHash("sha256").update(contenido).digest();
  const t = new Date();
  const p2 = (x) => String(x).padStart(2, "0");
  const utc = `${p2(t.getUTCFullYear() % 100)}${p2(t.getUTCMonth() + 1)}${p2(t.getUTCDate())}${p2(t.getUTCHours())}${p2(t.getUTCMinutes())}${p2(t.getUTCSeconds())}Z`;

  // Atributos firmados (SET OF ordenado por su codificación DER)
  const atributos = [
    seq(oid(OID.contentType), set(oid(OID.data))),
    seq(oid(OID.signingTime), set(tlv(0x17, Buffer.from(utc, "ascii")))),
    seq(oid(OID.messageDigest), set(octetos(digest))),
  ].sort(Buffer.compare);
  const atributosSet = set(...atributos);
  const firma = crypto.createSign("RSA-SHA256").update(atributosSet).sign(keyPem);

  const algSha256 = seq(oid(OID.sha256), nulo);
  const signerInfo = seq(
    entero(1),
    seq(emisor, serial),
    algSha256,
    Buffer.concat([Buffer.from([0xa0]), atributosSet.subarray(1)]), // [0] IMPLICIT
    seq(oid(OID.rsa), nulo),
    octetos(firma),
  );
  const signedData = seq(
    entero(1),
    set(algSha256),
    seq(oid(OID.data), ctx(0, octetos(contenido))),
    ctx(0, certDer),
    set(signerInfo),
  );
  return seq(oid(OID.signedData), ctx(0, signedData)).toString("base64");
}


const items = $input.all();
let cert = null, key = null;
for (let i = 0; i < items.length; i++) {
  const nombre = (items[i].binary?.data?.fileName || '').toLowerCase();
  const contenido = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
  if (nombre.endsWith('.crt')) cert = contenido;
  if (nombre.endsWith('.key')) key = contenido;
}
if (!cert || !key) throw new Error('Falta cecip.crt o cecip.key en la carpeta del certificado de ARCA');
const amb = $('Al ejecutarse desde otro workflow').first().json.ambiente;
const ahora = DateTime.now().setZone('America/Argentina/Buenos_Aires');
const tra = '<?xml version="1.0" encoding="UTF-8"?><loginTicketRequest version="1.0"><header>'
  + '<uniqueId>' + Math.floor(Date.now() / 1000) + '</uniqueId>'
  + '<generationTime>' + ahora.minus({ minutes: 10 }).toISO({ suppressMilliseconds: true }) + '</generationTime>'
  + '<expirationTime>' + ahora.plus({ minutes: 10 }).toISO({ suppressMilliseconds: true }) + '</expirationTime>'
  + '</header><service>wsfe</service></loginTicketRequest>';
const cms = firmarCms(tra, cert, key, crypto);
const xml = '<soapenv:Envelope xmlns:soapenv="http://schemas.xmlsoap.org/soap/envelope/" xmlns:wsaa="http://wsaa.view.sua.dvadac.desein.afip.gov">'
  + '<soapenv:Header/><soapenv:Body><wsaa:loginCms><wsaa:in0>' + cms + '</wsaa:in0></wsaa:loginCms></soapenv:Body></soapenv:Envelope>';
const url = amb === 'produccion' ? 'https://wsaa.afip.gov.ar/ws/services/LoginCms' : 'https://wsaahomo.afip.gov.ar/ws/services/LoginCms';
return [{ json: { xml, url } }];

const txt = String($input.first().json.data || '');
const des = txt.replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&amp;/g, '&');
const tomar = (tag) => (des.match(new RegExp('<' + tag + '>([\\s\\S]*?)</' + tag + '>')) || [])[1];
const token = tomar('token'), sign = tomar('sign'), expira = tomar('expirationTime');
if (!token || !sign) {
  const falla = tomar('faultstring') || 'ARCA no devolvió el ticket de acceso';
  return [{ json: { ok: false, error: 'WSAA: ' + falla.slice(0, 300) } }];
}
const ta = { token, sign, expira };
const bin = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(ta)), 'ta.json', 'application/json');
return [{ json: { ok: true, ...ta }, binary: { data: bin } }];
